"""Install a separate Steam publication request button and fixed systemd path activation."""
import os,hashlib,base64,fcntl,subprocess,time,tempfile
from pathlib import Path
MANIFEST={'automation/server/phone_ui.py': {'old': '633f5ed7d06d2976d669663eb71b88e6e950bc1093d3911c8567d25742a150dd', 'new': '89d399e347f8c409c6eda27e35791d74fb8379295bc6e5852b2a3b8ae0e7dbc4', 'body': ''}, 'automation/server/phone_view.py': {'old': '16993efedb7645e9590a951f526629cb6d01efa845d63439b4a5a8f6c9325051', 'new': 'ced80540ea9d2b4b1c98cd800da67d7aab4897943addcba99778265990a5026f', 'body': ''}, 'automation/server/fh6-steam-request.path': {'old': None, 'new': 'ad29bb877f1d8949b670b67faf565fdf83cb7ed1cc27f2eb65b0f36b2704ab4b', 'body': 'W1VuaXRdCkRlc2NyaXB0aW9uPVJ1biBTdGVhbSBwdWJsaXNoZXIgb24gYW4gb3duZXIgcGFuZWwgcmVxdWVzdAoKW1BhdGhdClBhdGhDaGFuZ2VkPS92YXIvbGliL2ZoNi9zdGVhbS1wdWJsaXNoLXJlcXVlc3QKVW5pdD1maDYtc3RlYW0uc2VydmljZQoKW0luc3RhbGxdCldhbnRlZEJ5PW11bHRpLXVzZXIudGFyZ2V0Cg=='}, 'automation/server/test_steam_refresh_button.py': {'old': None, 'new': 'a6126fd931747f3f323aaa5bccf14b4e07c5a4ab1237e947ab2bbb104524f086', 'body': ''}}
def replace(p,raw,stat=None):
    fd,name=tempfile.mkstemp(dir=p.parent,prefix='.handoff-install-')
    try:
        with os.fdopen(fd,'wb') as f:
            f.write(raw);f.flush();os.fsync(f.fileno());os.fchmod(f.fileno(),stat.st_mode&0o777 if stat else 0o644)
            if stat:os.fchown(f.fileno(),stat.st_uid,stat.st_gid)
        os.replace(name,p)
    finally:Path(name).unlink(missing_ok=True)
def main():
    assert os.geteuid()==0,'Root required'
    root=Path('/opt/fh6/repo');store=Path('/var/lib/fh6');prepared={}
    for n,m in MANIFEST.items():
        p=root/n;assert not p.is_symlink(),'Unexpected symlink'
        before=p.read_bytes() if p.exists() else None
        sha=hashlib.sha256(before).hexdigest() if before is not None else None
        assert sha==m['old'] or sha==m['new'],'Unexpected version: '+n+'; nothing changed'
        raw=base64.b64decode(m['body']);assert hashlib.sha256(raw).hexdigest()==m['new']
        if n.endswith('.py'):compile(raw,str(p),'exec')
        prepared[n]=(before,p.stat() if p.exists() else None,raw)
    lockpath=store/'runner.lock';assert not lockpath.is_symlink()
    with lockpath.open('rb') as lock:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        backup=store/'repairs'/('steam-button-'+str(time.time_ns()));backup.mkdir(mode=0o700)
        for n,(before,stat,raw) in prepared.items():
            if before is not None:
                saved=backup/n;saved.parent.mkdir(parents=True,exist_ok=True);saved.write_bytes(before);saved.chmod(0o600)
        unit_path=Path('/etc/systemd/system/fh6-steam-request.path')
        assert not unit_path.is_symlink(),'Unexpected path unit symlink'
        had_unit=unit_path.exists()
        applied=[]
        try:
            for n,(before,stat,raw) in prepared.items():replace(root/n,raw,stat);applied.append(n)
            subprocess.run(['/usr/bin/python3','-m','unittest','test_steam_refresh_button','test_phone_csrf','test_phone_view','test_steam_publish'],cwd=root/'automation/server',check=True,timeout=120)
            subprocess.run(['runuser','-u','fh6','--','/opt/fh6/venv/bin/python',str(root/'automation/server/test_incident_panel_browser.py')],cwd=root,check=True,timeout=120)
            unit=Path('/etc/systemd/system/fh6-steam-request.path')
            wanted=(root/'automation/server/fh6-steam-request.path').read_bytes()
            assert not unit.exists() or unit.read_bytes()==wanted,'Unexpected path unit'
            if not unit.exists():replace(unit,wanted)
            subprocess.run(['systemd-analyze','verify',str(unit)],check=True,timeout=30)
            subprocess.run(['systemctl','daemon-reload'],check=True,timeout=30)
            subprocess.run(['systemctl','enable','--now','fh6-steam-request.path'],check=True,timeout=30)
            subprocess.run(['systemctl','restart','fh6-phone.service'],check=True,timeout=30)
            subprocess.run(['systemctl','is-active','--quiet','fh6-phone.service','fh6-steam-request.path'],check=True,timeout=10)
        except Exception:
            if not had_unit and unit_path.exists():
                subprocess.run(['systemctl','disable','--now','fh6-steam-request.path'],check=False,timeout=30)
                unit_path.unlink()
                subprocess.run(['systemctl','daemon-reload'],check=False,timeout=30)
            for n in reversed(applied):
                before,stat,_=prepared[n]
                if before is None:(root/n).unlink(missing_ok=True)
                else:replace(root/n,before,stat)
            subprocess.run(['systemctl','restart','fh6-phone.service'],check=False,timeout=30)
            raise
        print('STEAM_BUTTON_INSTALLED separate Steam request; consent and submission guards retained; no publication requested',flush=True)
        print('BACKUP='+str(backup),flush=True)

if __name__=='__main__':main()
